const TIME_LIMIT: int = 2944;      // 120 opening buffer + 2820 source timeout + 4 startup margin
const OPENING_BUFFER: int = 120;
const GVAR_STOP: int = 16;         // 16..1023 script-owned globals; set when the segment ends
const TH16_TALISMAN: int = 528;    // source etSprite type 11, colors 4 / 10

// ---- Boss3_at / Boss3_at1B bullets (main boss), type 11 color 4 ----------
// Source EX chain (async=0, sequential): ANIM a=1 (birth offset only, applied as
// sh_dist) then four STEP records c=0,d=0,b=1:
//   a=30 r=+30deg / a=30 r=-60deg / a=30 r=+90deg / a=20 r=-120deg, last target
//   speed 1.0 (E/N) or 2.0 (H/L); earlier records keep the entering speed.
// STEP decelerates drawing velocity v(t)=v0*(1-t/a) then restores the logical
// speed and turns at the segment boundary -> linear step_speed(0,a) + turn + set_speed.
xformdef BOSS3_STEP(v0: fx, v1: fx) {
    @30 step_speed(0fx, 30);
    turn(30deg);
    set_speed(v0);
    @30 step_speed(0fx, 30);
    turn(-60deg);
    set_speed(v0);
    @30 step_speed(0fx, 30);
    turn(90deg);
    set_speed(v0);
    @20 step_speed(0fx, 20);
    turn(-120deg);
    set_speed(v1);
}
xformdef BOSS3_STEP1B(v0: fx, v1: fx) {
    @30 step_speed(0fx, 30);
    turn(-30deg);
    set_speed(v0);
    @30 step_speed(0fx, 30);
    turn(60deg);
    set_speed(v0);
    @30 step_speed(0fx, 30);
    turn(-90deg);
    set_speed(v0);
    @20 step_speed(0fx, 20);
    turn(120deg);
    set_speed(v1);
}

// ---- Boss3B_at / Boss3B_at1B bullets (BossB), type 11 color 10 -----------
// Source EX chain: ANIM a=1 (offset via sh_dist), OFFSCREEN a=240 b=0,
// ANGLE_ACCEL a=600 r=0.008 px/frame^2 s=+/-0.008726646 rad/frame (0.5 deg/frame).
xformdef BOSSB_SPIN_CW {
    offscreen_keep(240);
    set_ang_vel(0.5deg);
    @600 set_accel(0.008fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}
xformdef BOSSB_SPIN_CCW {
    offscreen_keep(240);
    set_ang_vel(-0.5deg);
    @600 set_accel(0.008fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// ---- Boss3_at: 10 volleys, 20 frames apart; fixed ring base 90deg -2deg/volley
sub boss3_at() {
    var base: angle = 90deg;
    var n: int = 16;
    var spd: fx = 2fx;
    var vf: fx = 1fx;
    var d: fx = 12fx;              // etDist 20 - 4*2.0 (ANIM birth offset)
    if global(GVAR_RANK) >= RANK_LUNATIC {
        n = 24;
        spd = 3.5fx;
        vf = 2fx;
        d = 6fx;                   // 20 - 4*3.5
    }
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, d);
    sh_xform(0, BOSS3_STEP(spd, vf));
    for i in 0..10 {
        sh_angle(0, base, 0deg);
        sh_fire(0);
        wait(20);
        base = base - 2deg;
        if global(GVAR_STOP) != 0 { return; }
    }
}

