// ---- moveRand(60,4,1.0) per movement.md recipe: 60 linear steps 1.0->0,
// per-tick clamp to the entry moveLimit rectangle. Enemy slots:
// self_int(0)=next step count, self_fx(0/1)=logical unit direction.
sub arm_next(ylo: fx, yhi: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 60 { sp = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -72fx { nx = -72fx; }
    if nx > 72fx { nx = 72fx; }
    if ny < ylo { ny = ylo; }
    if ny > yhi { ny = yhi; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_begin(ylo: fx, yhi: fx, iylo: fx, iyhi: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -36fx {
        a = r / 3;
    } else if $self_x > 36fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var pick: int = rand(65536) % 3;
        if $player_x > $self_x {
            if pick == 0 { a = a + 32768; }
        } else {
            if pick != 0 { a = a + 32768; }
        }
    }
    if $self_y < iylo {
        if a < 0 { a = -a; }
    } else if $self_y > iyhi {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next(ylo, yhi);
}

sub card_wait(frames: int, ylo: fx, yhi: fx) {
    for i in 0..frames {
        wait(1);
        arm_next(ylo, yhi);
    }
}

// ---- Boss3p entry (main boss). Entry state: (64,128) from Boss init.
async sub boss_a() {
    set_invuln(65535);
    set_hurtbox(20fx);                       // source setHurtbox(40,40)
    set_hitbox(24fx);                        // source setHitbox(48,48)
    move_vel(0, 0deg, 0fx, EASE_LINEAR);     // moveVel(0,0) / moveVelTime(0,...)
    move_to(120, 0fx, 144fx, EASE_QUAD_OUT); // movePosTime(120,4,0,144)
    wait(120);
    wait(60);                                // source 180 frames before first Boss3_at
    loop {
        if global(GVAR_STOP) != 0 { return; }
        boss3_at();
        wait(20);
        move_rand_begin(96fx, 160fx, 112fx, 144fx);   // moveLimit(0,128,144,64)
        card_wait(70, 96fx, 160fx);
        boss3_at1b();
        wait(20);
        move_rand_begin(96fx, 160fx, 112fx, 144fx);
        card_wait(70, 96fx, 160fx);
    }
}

// ---- Boss3Bp entry (BossB). Entry state: (-64,128) from BossB init.
async sub boss_b() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(120, 0fx, 64fx, EASE_QUAD_OUT);  // movePosTime(120,4,0,64)
    wait(120);
    wait(60);
    loop {
        if global(GVAR_STOP) != 0 { return; }
        boss3b_at();
        wait(20);
        move_rand_begin(32fx, 96fx, 48fx, 80fx);      // moveLimit(0,64,144,64)
        card_wait(70, 32fx, 96fx);
        boss3b_at1b();
        wait(20);
        move_rand_begin(32fx, 96fx, 48fx, 80fx);
        card_wait(70, 32fx, 96fx);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(64fx, 128fx, 16300, 0, 0, 0, boss_a);
    _ = spawn_enemy(-64fx, 128fx, 16300, 0, 0, 0, boss_b);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    set_global(GVAR_STOP, 1);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
